snippet_css:
:root{
  --bg: #F4EBD9;
  --fg: #2A1E17;
  --muted: #5A4632;
  --surface: #FBF5E8;
  --border: #C9A227;
  --accent: #6D1A36;
  --accent-fg: #FBF5E8;
  --radius: 2px;
  --radius-sm: 2px;
  --shadow: 0 8px 22px rgba(42,30,23,.16);
  --btn-shadow: 0 3px 0 rgba(109,26,54,.42);
  --art-bg: radial-gradient(circle at 50% 40%,#8A2A4B,#2A1E17);
  --media-bg: linear-gradient(180deg,#FBF5E8,#E7D9BD);
  --cta-bg: #EFE3C8;
  --input-bg: #FBF5E8;
  --ok: #1F3B2D;
  --warn: #8A2A4B;
  --font-display: 'Cormorant Garamond','Noto Serif TC',serif;
  --font-body: 'EB Garamond','Noto Serif TC',serif;
  --font-mono: 'EB Garamond',ui-monospace,serif;
  --focus-ring: var(--accent);
}

snippet_tailwind:
